
(function(){
 const frame=document.getElementById('readingRoomInlineFrame');
 if(!frame) return;
 const payload='';
 const bytes=Uint8Array.from(atob(payload),c=>c.charCodeAt(0));
 const readingRoomHTML=new TextDecoder('utf-8').decode(bytes);
 frame.srcdoc=readingRoomHTML;
 // Open the complete Reading Room as a standalone browser tab, never inside the portfolio section.
 window.openReadingRoomStandalone=function(){
   const readerWindow=window.open('about:blank','_blank');
   if(!readerWindow){
     window.alert('Your browser blocked the new tab. Allow pop-ups for this portfolio, then select Product craft again.');
     return;
   }
   readerWindow.document.open();
   readerWindow.document.write(readingRoomHTML);
   readerWindow.document.close();
 };
})();
